//! Font selection on Linux identical to real Qt 6.12 (`tests/data/linux_fonts_golden.txt`, regenerated by
//! `tests/data/gen_linux_fonts_golden.py`): which font file a family name, weight and slant resolve to
//! (`QFontconfigDatabase::populateFontDatabase` registers what `FcFontList` returns, `QFontDatabasePrivate::match`
//! and `bestStyle` pick a face by weight, stretch and slant, and a family that is not there is replaced by the
//! first family of `fallbacksForFamily`, i.e. `FcFontSort`), which font a character gets when the primary font
//! has no glyph for it (`QFontEngineMulti`, one fallback list per script item), and the advances that follow.
//!
//! The result depends on every installed font and on fontconfig's rules, so a chunk of the golden (one `fontset`
//! line and the lines below it) is compared only when this machine has the font files and the language it was
//! measured with. The golden holds the chunks of the Linux development host and of GitHub's ubuntu-22.04 runner.
#![cfg(all(unix, not(target_os = "macos")))]

use ferrokit_gui::text::font::{Font, FontStyle, FontWeight, StyleHint};
use ferrokit_gui::text::font_database::{
    resolve_font_engines_for_text_global, set_application_device_pixel_ratio,
};
use ferrokit_gui::text::font_metrics::FontMetrics;
use ferrokit_gui::text::glyph_layout::{FontEngine, GlyphLayout};
use rustybuzz::ttf_parser::{Face, PlatformId, Tag, name_id};

const GOLDEN: &str = include_str!("data/linux_fonts_golden.txt");

fn fnv1a64(data: &[u8]) -> u64 {
    data.iter().fold(0xcbf2_9ce4_8422_2325u64, |h, &b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)
    })
}

fn text(id: &str) -> &'static str {
    match id {
        "l" => "Hamburgefonstiv 0123 AVAWTo",
        "a" => "\u{627}\u{644}\u{639}\u{631}\u{628}\u{64a}\u{629}",
        "A" => "\u{627}\u{644}\u{639}\u{631}\u{628}\u{64a}\u{629} \u{639}\u{631}\u{628}\u{64a}",
        "h" => "\u{5e9}\u{5dc}\u{5d5}\u{5dd}",
        "d" => "\u{928}\u{92e}\u{938}\u{94d}\u{924}\u{947}",
        "b" => "\u{9ac}\u{9be}\u{982}\u{9b2}\u{9be}",
        "m" => "\u{ba4}\u{bae}\u{bbf}\u{bb4}\u{bcd}",
        "t" => "\u{e2a}\u{e27}\u{e31}\u{e2a}\u{e14}\u{e35}",
        "s" => "\u{dc3}\u{dd2}\u{d82}\u{dc4}\u{dbd}",
        "k" => "\u{c548}\u{b155}\u{d558}\u{c138}\u{c694}",
        "j" => "\u{3072}\u{3089}\u{304c}\u{306a}\u{30ab}\u{30bf}\u{30ab}\u{30ca}",
        "c" => "\u{4e2d}\u{6587}\u{5b57}\u{6f22}\u{5b57}",
        "g" => "\u{3b1}\u{3b2}\u{3b3} \u{394}\u{3a9}",
        "r" => "\u{436}\u{443}\u{43a} \u{42f}",
        "n" => "\u{540}\u{561}\u{575}\u{565}\u{580}\u{565}\u{576}",
        "o" => "\u{10e5}\u{10d0}\u{10e0}\u{10d7}\u{10e3}\u{10da}\u{10d8}",
        "y" => "\u{2605}\u{2713}\u{2192}\u{2211}\u{2665}\u{a9}\u{20ac}",
        "x" => "\u{250c}\u{2500}\u{2510}\u{2588}\u{2591}",
        "e" => "Hi \u{1F600}\u{1F389} \u{2600}\u{2714}",
        "u" => "\u{2200}\u{2202}\u{2208}\u{211d}\u{221e}",
        "w" => "a\u{a0}b",
        "z" => {
            "abc \u{627}\u{644}\u{639}\u{631}\u{628} \u{6f22}\u{5b57} \u{2713} \u{1F600} \u{928} z"
        }
        other => panic!("no text {other}"),
    }
}

fn hint_of(name: &str) -> StyleHint {
    match name {
        "-" => StyleHint::AnyStyle,
        "SansSerif" => StyleHint::SansSerif,
        "Serif" => StyleHint::Serif,
        "TypeWriter" => StyleHint::TypeWriter,
        "Monospace" => StyleHint::Monospace,
        "Cursive" => StyleHint::Cursive,
        "Fantasy" => StyleHint::Fantasy,
        "System" => StyleHint::System,
        "OldEnglish" => StyleHint::OldEnglish,
        other => panic!("hint {other}"),
    }
}

fn hex(field: &str) -> u64 {
    u64::from_str_radix(field, 16).expect("hash")
}

/// `<PostScript name with _ for spaces>#<head.checkSumAdjustment>`: what the generator calls a face id.
fn face_id(engine: &FontEngine) -> String {
    let Some(data) = engine.raw_data.as_ref() else {
        // The box engine has no font file.
        return "box".to_string();
    };
    let Ok(face) = Face::parse(data.as_slice(), engine.face_index) else {
        return "unparsable".to_string();
    };
    let mut best: Option<(u8, String)> = None;
    for name in face.names() {
        if name.name_id != name_id::POST_SCRIPT_NAME {
            continue;
        }
        let (rank, text) = match name.platform_id {
            PlatformId::Windows | PlatformId::Unicode => (0, name.to_string()),
            PlatformId::Macintosh => (1, Some(name.name.iter().map(|&b| b as char).collect())),
            _ => continue,
        };
        if best.as_ref().is_none_or(|(r, _)| rank < *r)
            && let Some(text) = text
        {
            best = Some((rank, text));
        }
    }
    // The box engine's stand-in font has no `name` table.
    let Some((_, ps)) = best else {
        return "box".to_string();
    };
    let ps = ps.replace(' ', "_");
    let head = face
        .raw_face()
        .table(Tag::from_bytes(b"head"))
        .filter(|t| t.len() >= 12)
        .map_or_else(
            || "nohead".to_string(),
            |t| format!("{:02x}{:02x}{:02x}{:02x}", t[8], t[9], t[10], t[11]),
        );
    format!("{ps}#{head}")
}

fn primary_face_id(font: &Font) -> String {
    resolve_font_engines_for_text_global(font, "")
        .first()
        .map_or_else(|| "none".to_string(), face_id)
}

/// The runs of a text as the generator prints them: `<face id>:<characters>` per run of characters whose
/// glyphs come from the same face.
fn runs(font: &Font, text: &str) -> String {
    let engines = resolve_font_engines_for_text_global(font, text);
    let layout = GlyphLayout::shape_with_engines(text, font, &engines);
    let mut by_cluster: Vec<(usize, usize, u16)> = layout
        .glyphs
        .iter()
        .map(|g| (g.cluster, usize::from(g.font_index), g.glyph_id))
        .collect();
    by_cluster.sort_by_key(|&(cluster, ..)| cluster);
    let mut runs: Vec<(String, usize)> = Vec::new();
    for (offset, _) in text.char_indices() {
        let at = by_cluster.partition_point(|&(cluster, ..)| cluster <= offset);
        let id = match at.checked_sub(1) {
            // No engine has the character: which font draws the missing-glyph box is not
            // observable in Qt's glyph runs.
            Some(i) if by_cluster[i].2 == 0 => "0".to_string(),
            Some(i) => engines
                .get(by_cluster[i].1)
                .map_or_else(|| "none".to_string(), face_id),
            None => "none".to_string(),
        };
        match runs.last_mut() {
            Some((last, count)) if *last == id => *count += 1,
            _ => runs.push((id, 1)),
        }
    }
    runs.iter()
        .map(|(id, count)| format!("{id}:{count}"))
        .collect::<Vec<_>>()
        .join(" ")
}

fn fixed64(value: f32) -> i64 {
    let fixed = f64::from(value) * 64.0;
    assert_eq!(
        fixed,
        fixed.round(),
        "{value} is not a whole number of 1/64 px"
    );
    fixed as i64
}

/// The `fontset` header of this machine as the generator prints it: the number and the hash of the sorted,
/// distinct paths of the font files fontconfig lists (`fc-list`), and the language `FcDefaultSubstitute` adds.
fn fontset() -> Option<(usize, u64, String)> {
    let out = std::process::Command::new("fc-list")
        .args(["--format", "%{file}\\n"])
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let listing = String::from_utf8_lossy(&out.stdout).into_owned();
    let mut paths: Vec<&str> = listing.lines().filter(|l| !l.is_empty()).collect();
    paths.sort_unstable();
    paths.dedup();
    let blob: String = paths.iter().map(|p| format!("{p}\n")).collect();
    let lang = ["LC_ALL", "LC_CTYPE", "LANG"]
        .iter()
        .find_map(|var| std::env::var(var).ok().filter(|v| !v.is_empty()))
        .unwrap_or_else(|| "-".to_string());
    Some((paths.len(), fnv1a64(blob.as_bytes()), lang))
}

fn font_of(fields: &[&str]) -> Font {
    // `<family> <hint> <weight> <italic>`
    let family = if fields[0] == "_" {
        String::new()
    } else {
        fields[0].replace('_', " ")
    };
    let weight: u32 = fields[2].parse().expect("weight");
    let mut font = Font::new(&family, 16.0)
        .with_style_hint(hint_of(fields[1]))
        .with_weight(if weight >= 600 {
            FontWeight::Bold
        } else {
            FontWeight::Normal
        });
    if fields[3] == "1" {
        font.set_style(FontStyle::Italic);
    }
    font
}

#[test]
fn linux_font_selection_is_identical_to_qt() {
    set_application_device_pixel_ratio(1.0);
    let Some((count, hash, lang)) = fontset() else {
        eprintln!("NOTHING COMPARED: fc-list is not available");
        return;
    };
    let mut compared = 0;
    let mut failures = Vec::new();
    let mut same_fonts = false;
    for line in GOLDEN
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
    {
        let fields: Vec<&str> = line.split(' ').collect();
        match fields[0] {
            "fontset" => {
                same_fonts = fields[1].parse::<usize>().unwrap() == count
                    && hex(fields[2]) == hash
                    && fields[3] == lang;
                if !same_fonts {
                    eprintln!(
                        "skipping the chunk measured with {} font files ({}, {}): this machine has {count} ({hash:016x}, {lang})",
                        fields[1], fields[2], fields[3]
                    );
                }
            }
            _ if !same_fonts => {}
            "face" => {
                // `face <family> <hint> <weight> <italic> <face id> (adv <text id> <1/64 px>)*`
                let font = font_of(&fields[1..5]);
                let mut got = vec![primary_face_id(&font)];
                let mut want = vec![fields[5].to_string()];
                for advance in fields[6..].chunks(3) {
                    let ferrokit = FontMetrics::from_font(&font)
                        .horizontal_advance_exact(text(advance[1]), &font);
                    got.push(format!("adv {} {}", advance[1], fixed64(ferrokit)));
                    want.push(format!("adv {} {}", advance[1], advance[2]));
                }
                compared += 1;
                for (got, want) in got.iter().zip(&want) {
                    if got != want {
                        failures.push(format!("{line}: {got}, Qt {want}"));
                        break;
                    }
                }
            }
            "runs" => {
                // `runs <family> <hint> <weight> <italic> <text id> <1/64 px> <face id>:<n> ...`
                let font = font_of(&fields[1..5]);
                let got = runs(&font, text(fields[5]));
                let advance =
                    FontMetrics::from_font(&font).horizontal_advance_exact(text(fields[5]), &font);
                let got = format!("{} {got}", fixed64(advance));
                let want = fields[6..].join(" ");
                compared += 1;
                if got != want {
                    failures.push(format!("{}: {got}, Qt {want}", fields[..6].join(" ")));
                }
            }
            other => panic!("golden line {other}"),
        }
    }
    if compared == 0 {
        // The chains depend on every installed font, so a machine with another font set (a new runner image)
        // has nothing to compare until `gen_linux_fonts_golden.py` has measured it; say so rather than pass
        // quietly.
        eprintln!(
            "NOTHING COMPARED: no chunk of the golden was measured with the {count} font files ({hash:016x}, {lang}) of this machine"
        );
    }
    assert!(
        failures.is_empty(),
        "{} of {compared} differ from Qt:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
